import{_ as e,o as r,c as o,ae as a}from"./chunks/framework.Dh1jimFm.js";const g=JSON.parse('{"title":"Exporting Translations","description":"","frontmatter":{},"headers":[],"relativePath":"import-export/exporting.md","filePath":"import-export/exporting.md"}'),i={name:"import-export/exporting.md"};function l(n,t,s,p,h,u){return r(),o("div",null,t[0]||(t[0]=[a('<h1 id="exporting-translations" tabindex="-1">Exporting Translations <a class="header-anchor" href="#exporting-translations" aria-label="Permalink to &quot;Exporting Translations&quot;">​</a></h1><p>When you’re done translating, export in a format that matches your workflow.</p><h2 id="export-steps" tabindex="-1">Export steps <a class="header-anchor" href="#export-steps" aria-label="Permalink to &quot;Export steps&quot;">​</a></h2><ol><li>Go to <strong>File → Export</strong></li><li>Choose an export type (for example DOCX, bilingual table, or a CAT return format)</li><li>Pick a destination and save</li></ol><h2 id="cat-tool-round-trips" tabindex="-1">CAT tool round-trips <a class="header-anchor" href="#cat-tool-round-trips" aria-label="Permalink to &quot;CAT tool round-trips&quot;">​</a></h2><p>If you started from a CAT exchange format (memoQ/Trados/Phrase/CafeTran), export the matching return format.</p><h3 id="important-rules-for-round-trips" tabindex="-1">Important rules for round-trips <a class="header-anchor" href="#important-rules-for-round-trips" aria-label="Permalink to &quot;Important rules for round-trips&quot;">​</a></h3><ul><li><strong>Segment count must match</strong>: don’t merge or split segments.</li><li><strong>Keep tags balanced</strong>: for example <code>&lt;b&gt;text&lt;/b&gt;</code> (not <code>&lt;b&gt;text</code>).</li><li><strong>Don’t “pretty edit” bilingual tables</strong>: changing the table structure in Word can break reimport.</li><li>Run your CAT tool’s QA after reimport.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Don’t merge or split segments in Supervertaler when you plan to reimport into a CAT tool.</p></div><h2 id="choosing-the-right-export" tabindex="-1">Choosing the right export <a class="header-anchor" href="#choosing-the-right-export" aria-label="Permalink to &quot;Choosing the right export&quot;">​</a></h2><ul><li>For CAT tool workflows, use the matching CAT export: <ul><li>memoQ bilingual DOCX</li><li>Trados return package (SDLRPX) when you imported SDLPPX</li><li>Phrase bilingual DOCX</li><li>CafeTran bilingual table DOCX</li></ul></li><li>For review-only delivery, consider <a href="./bilingual-tables.html">Bilingual Tables</a>.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./formats.html">Supported File Formats</a></li><li><a href="./bilingual-tables.html">Bilingual Tables</a></li><li><a href="./../cat-tools/overview.html">CAT Tool Overview</a></li></ul>',13)]))}const m=e(i,[["render",l]]);export{g as __pageData,m as default};
